def main():
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()))
    total = 0
    for cid in IDS:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        assert set(rec.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
        t = rec["trigger"]
        assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
        assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))
        assert 0.0 <= rec["confidence"] <= 1.0
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        total += os.path.getsize(path)
    cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
    ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
    di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
    print(f"written={len(IDS)} changed_main={cm} reserve_used={ru} disputed={di} total_bytes={total}")

if __name__ == "__main__":
    main()
